                    result = self._run(user_message, stream=stream, stream_callback=stream_callback)
                    status = derive_run_status(trace.run, has_output=bool(result))
                    self.observability.finish_run(status=status, output=result)
                    self.last_run_trace = trace.finish(status=status, output=result)
                    return result
                except BaseException as exc:
                    self.observability.finish_run(status="inconclusive", error=exc)
                    self.last_run_trace = trace.finish(status="inconclusive")
                    raise
        finally:
            self._active_trace = None
            self._offered_tool_names = None

    def _usable_context_tokens(self) -> int:
        """Provider tokens available for the request after reserving the reply."""
        context_window = get_model_context_window(
            self.config["llm"]["model"],
            override=self.config["llm"].get("context_window") or None,
        )
        response_reserve = max(1024, int(self.config["llm"].get("max_tokens", 8192)))
        safety_margin = 1024
        return max(1, context_window - response_reserve - safety_margin)

    def _calibrate_token_estimate(
        self,
        messages: list[dict[str, Any]],
        tools: list[dict] | None,
        prompt_tokens: Any,
    ) -> None:
        """Scale local estimates by the provider's own count of the last request.

        The local tokenizer (cl100k) can differ from the model's by tens of
        percent; the provider's reported prompt tokens are exact.
        """
        if type(prompt_tokens) is not int or prompt_tokens <= 0:
            return
        estimated = estimate_total_request_tokens(messages, tools=tools)
        if estimated <= 0:
            return
        low, high = _TOKEN_CALIBRATION_BOUNDS
        self._token_calibration = min(high, max(low, prompt_tokens / estimated))

    def _compact_if_needed(
        self,
        api_messages: list[dict[str, Any]],
        tools: list[dict[str, Any]] | None,
        force: bool = False,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """Compact the request to fit the model window without an extra LLM call.

        Returns the (possibly compacted) ``(api_messages, conversation_messages)``
        pair. When ``force`` is set (e.g. after a provider overflow error) the
        target budget is halved to shed context aggressively.
        """
        total_tokens = estimate_total_request_tokens(api_messages, tools=tools)
        active_budget = self._usable_context_tokens()
        if force:
            active_budget = max(1, active_budget // 2)
        # The budget is in provider tokens; estimates are local tokenizer counts.
        active_budget = max(1, int(active_budget / self._token_calibration))

        if total_tokens <= active_budget:
            return api_messages, self.messages

        microcompact_cfg = self.config.get("microcompact", {})
        keep_recent = int(microcompact_cfg.get("keep_recent", 6))
        conversation_budget = active_budget - estimate_total_request_tokens([], tools=tools)
        if conversation_budget < 1:
            raise ContextBudgetError("Tool definitions leave no room for conversation context")
        compacted = compact_to_token_budget(
            api_messages,
            max_tokens=conversation_budget,
            keep_recent=keep_recent,
            strip_tool_results=microcompact_cfg.get("enabled", True),
        )
        compacted = _normalize_message_history(compacted)
        compacted_tokens = estimate_total_request_tokens(compacted, tools=tools)
        if compacted_tokens > active_budget:
            raise ContextBudgetError(
                "System prompt and active conversation cannot fit the model context window"
            )
        if compacted_tokens < total_tokens:
            logger.info(
                "Deterministic compaction: %d → %d tokens (saved %d)",
                total_tokens,
                compacted_tokens,
                total_tokens - compacted_tokens,
            )
            conversation = self._conversation_messages_from_api(compacted)
            note_needed = not any(
                isinstance(m.get("content"), str)
                and m["content"].startswith(_COMPACTION_NOTE_PREFIX)
                for m in compacted
            )
            if note_needed:
                noted = [*compacted, _COMPACTION_NOTE]
                if estimate_total_request_tokens(noted, tools=tools) <= active_budget:
                    compacted = noted
            return compacted, conversation

        logger.warning(
            "Context remains above active budget: %d > %d tokens; "
            "historical retrieval may be needed",
            total_tokens,
            active_budget,
        )
        return api_messages, self.messages

    def _run(
        self,
        user_message: str,
        stream: bool = True,
        stream_callback: Callable[[str], None] | None = None,
"""LLM provider layer — client construction and OpenAI-compatible adapters.

All provider knowledge lives here so the agent loop stays provider-agnostic.
"""

from __future__ import annotations

import logging
from collections.abc import Callable
from typing import Any

from openai import OpenAI

logger = logging.getLogger(__name__)


def build_client(llm_config: dict) -> Any:
    """Construct the OpenAI-compatible SDK client for the configured endpoint."""
    return OpenAI(
        api_key=REDACTED,
        base_url=llm_config["base_url"],
        timeout=120.0,
        max_retries=0,
    )


def completion_request_kwargs(payload: dict[str, Any], stream: bool = False) -> dict[str, Any]:
    request_kwargs: dict[str, Any] = {
        "model": payload["model"],
        "messages": payload["messages"],
        "temperature": payload.get("temperature", 0.7),
        "top_p": payload.get("top_p", 1.0),
    }
    if payload.get("max_tokens"):
        request_kwargs["max_tokens"] = payload["max_tokens"]
    if payload.get("tools"):
        request_kwargs["tools"] = payload["tools"]
        request_kwargs["tool_choice"] = "auto"
    if "extra_body" in payload:
        request_kwargs["extra_body"] = payload["extra_body"]
    if stream:
        request_kwargs["stream"] = True
        if payload.get("stream_include_usage", True):
            request_kwargs["stream_options"] = {"include_usage": True}
    return request_kwargs


def chat_completion(client: Any, payload: dict[str, Any]) -> dict:
    """Non-streaming OpenAI-compatible completion, normalized to agent shape."""
    request_kwargs = completion_request_kwargs(payload)
    resp = client.chat.completions.create(**request_kwargs)  # type: ignore[call-overload]
    message = resp.choices[0].message
    return {
        "choices": [
            {
                "finish_reason": (
                    resp.choices[0].finish_reason
                    if isinstance(resp.choices[0].finish_reason, str)
                    else None
                ),
                "message": {
                    "role": "assistant",
                    "content": message.content,
                    "tool_calls": (
                        [tc.model_dump() for tc in message.tool_calls]
                        if message.tool_calls
                        else None
                    ),
                    "reasoning_content": (message.model_extra or {}).get("reasoning_content"),
                },
            }
        ],
        "usage": resp.usage.model_dump() if resp.usage else None,
    }


def stream_response(
    client: Any,
    payload: dict,
    callback: Callable[[str], None] | None = None,
    reasoning_callback: Callable[[str], None] | None = None,
    interrupt_check: Callable[[], bool] | None = None,
) -> dict:
    """Stream a response from an OpenAI-compatible endpoint."""
    full_content = ""
    full_reasoning = ""
    tool_calls: list[dict[str, Any]] = []
    interrupted = False
    finish_reason: str | None = None

    request_kwargs = completion_request_kwargs(payload, stream=True)

    with client.chat.completions.create(**request_kwargs) as stream:  # type: ignore[call-overload]
        usage: dict[str, Any] | None = None
        for chunk in stream:
            # Most providers send usage on a trailing choice-less chunk; some
            # attach it to the final chunk that still carries a choice.
            chunk_usage = getattr(chunk, "usage", None)
            if chunk_usage is not None and hasattr(chunk_usage, "model_dump"):
                dumped_usage = chunk_usage.model_dump()
                if isinstance(dumped_usage, dict):
                    usage = dumped_usage
            if not chunk.choices:
                continue
            chunk_finish_reason = chunk.choices[0].finish_reason
            if isinstance(chunk_finish_reason, str):
                finish_reason = chunk_finish_reason
            delta = chunk.choices[0].delta

            if interrupt_check is not None and interrupt_check():
                logger.info("Stream interrupted by user")
                interrupted = True
                break

            if delta.content:
                full_content += delta.content
                if callback:
                    callback(delta.content)

            if delta.tool_calls:
                for tc in delta.tool_calls:
                    index = tc.index
                    while index >= len(tool_calls):
                        tool_calls.append(
                            {
                                "id": "",
                                "type": "function",
                                "function": {"name": "", "arguments": ""},
                            }
                        )
                    if tc.id:
                        tool_calls[index]["id"] = tc.id
                    if tc.function:
                        if tc.function.name:
                            tool_calls[index]["function"]["name"] = tc.function.name
                        if tc.function.arguments:
                            tool_calls[index]["function"]["arguments"] += tc.function.arguments

            extra = delta.model_extra or {}
            reasoning_chunks: list[str] = []
            for key in ("reasoning", "reasoning_content"):
                value = extra.get(key)
                if isinstance(value, str):
                    reasoning_chunks.append(value)
            details = extra.get("reasoning_details")
            if not reasoning_chunks and isinstance(details, list):
                for detail in details:
                    if isinstance(detail, dict):
                        value = detail.get("text") or detail.get("content")
                        if isinstance(value, str):
                            reasoning_chunks.append(value)
            for reasoning in reasoning_chunks:
                full_reasoning += reasoning
                if reasoning_callback:
                    reasoning_callback(reasoning)

    reasoning_content_value: str | None = full_reasoning if full_reasoning else None
    if not reasoning_content_value and tool_calls:
        reasoning_content_value = ""

    return {
        "choices": [
            {
                "finish_reason": finish_reason,
                "message": {
                    "role": "assistant",
                    "content": full_content if full_content else None,
                    "tool_calls": None if interrupted else (tool_calls if tool_calls else None),
                    "reasoning_content": reasoning_content_value,
                },
            }
        ],
        "usage": usage,
    }
"""Tool execution pipeline.

Every tool call runs through one sequence:
parse -> workspace defaults -> policy -> confirmation -> hooks -> dispatch
-> transient retry -> verification -> trace and observability.
"""

from __future__ import annotations

import contextvars
import functools
import json
import logging
import threading
import time
import uuid
from collections.abc import Callable
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Any, Literal

from nova.context import label_external_content
from nova.harness import VerificationResult
from nova.hooks import EVENT_POST_TOOL_CALL, EVENT_PRE_TOOL_CALL, hooks
from nova.mcp_client import McpToolInfo
from nova.observability import redact
from nova.permissions import PermissionResult, has_untrusted_output, is_egress_tool
from nova.tool_catalog import DISCOVERY_TOOL
from nova.tools.registry import ToolEntry, registry
from nova.tools.result import ToolResult

if TYPE_CHECKING:
    from nova.agent import NovaAgent

logger = logging.getLogger(__name__)

MCP_RESOURCE_TOOL = "mcp_read_resource"

_MAX_PARALLEL_TOOLS = 4

# Harness traces have no "interrupted" outcome; an interruption is a failed
# call whose verification is inconclusive.
_TRACE_OUTCOMES: dict[str, Literal["completed", "failed", "denied"]] = {
    "completed": "completed",
    "failed": "failed",
    "denied": "denied",
    "interrupted": "failed",
}


@dataclass(frozen=True)
class _Call:
    id: str
    name: str
    arguments: dict[str, Any] | None
    parse_error: ToolResult | None = None


class ToolExecutor:
    """Runs one agent's tool calls.

    UI and protocol layers set callbacks (`_interrupt_check`,
    `_confirmation_callback`, `_tool_callback`, `_tool_lifecycle_callback`)
    on the agent at any time, so they are read from the agent on each use.
    """

    def __init__(self, agent: NovaAgent) -> None:
        self._agent = agent
        self._mcp_lock = threading.RLock()
        # Set once output from the web, HTTP, or MCP is in the conversation; it
        # may carry injected instructions, so outbound tools then need approval.
        self.untrusted_content_seen = False
        self._untrusted_output_pending = False

    def run_batch(self, tool_calls: list[dict]) -> list[ToolResult]:
        """Run one model response's tool calls, read-only ones in parallel."""
        parallel: list[tuple[int, dict]] = []
        sequential: list[tuple[int, dict]] = []
        for index, tool_call in enumerate(tool_calls):
            target = parallel if self._can_run_in_parallel(tool_call) else sequential
            target.append((index, tool_call))

        results: list[ToolResult | None] = [None] * len(tool_calls)
        for tool_call in tool_calls:
            self._report_start(tool_call)

        if parallel:
            with ThreadPoolExecutor(max_workers=min(len(parallel), _MAX_PARALLEL_TOOLS)) as pool:
                futures = {}
                for index, tool_call in parallel:
                    self._announce(tool_call)
                    context = contextvars.copy_context()
                    futures[pool.submit(context.run, self.run, tool_call)] = index
                for future in as_completed(futures):
                    index = futures[future]
                    results[index] = self._guarded(future.result, tool_calls[index])
                    self._report_result(tool_calls[index], results[index])

        for index, tool_call in sequential:
            if self._interrupted():
                results[index] = ToolResult.interrupted()
            else:
                self._announce(tool_call)
                results[index] = self._guarded(functools.partial(self.run, tool_call), tool_call)
            self._report_result(tool_call, results[index])

        # The model sees this batch's output only in its next response, so the
        # stricter policy starts with the next batch.
        if self._untrusted_output_pending:
            self.untrusted_content_seen = True
            self._untrusted_output_pending = False

        return [
            result if result is not None else ToolResult.failed("Error: Tool produced no result")
            for result in results
        ]

    def skip_batch(self, tool_calls: list[dict]) -> list[ToolResult]:
        """Record a batch the user interrupted before any call started."""
        collector = self._agent._active_trace
        results = []
        for tool_call in tool_calls:
            result = ToolResult.interrupted()
            self._report_start(tool_call)
            if collector is not None:
                call = self._parse(tool_call)
                trace = collector.start_tool(call.id, call.name, redact(call.arguments or {}))
                collector.finish_tool(
                    trace,
                    outcome="failed",
                    result=result.content,
                    verification=VerificationResult("inconclusive", reason="interrupted"),
                )
            self._report_result(tool_call, result)
            results.append(result)
        return results

    def run(self, tool_call: dict) -> ToolResult:
        """Run one tool call through the full pipeline."""
        started = time.monotonic()
        call = self._parse(tool_call)
        collector = self._agent._active_trace
        trace = (
            collector.start_tool(call.id, call.name, redact(call.arguments or {}))
            if collector
            else None
        )

        def record_policy(permission: PermissionResult) -> None:
        if not isinstance(uri, str) or not uri:
            return "Error: uri must be a non-empty string"
        mcp_client = self._agent.mcp_client
        if not mcp_client.is_connected(server_name):
            return f"Error: MCP server '{server_name}' is not connected."
        with self._mcp_lock:
            return mcp_client.read_resource(server_name, uri)

    def _verify(self, call: _Call, result: ToolResult, *, ran: bool) -> VerificationResult | None:
        entry = registry.get_tool(call.name)
        if ran and entry is not None and entry.verifier is not None and call.arguments is not None:
            try:
                return entry.verifier(call.arguments, result.content, agent=self._agent)
            except Exception as exc:
                return VerificationResult("inconclusive", reason=type(exc).__name__)
        if result.status in ("failed", "denied"):
            return VerificationResult("failed", reason=f"tool call {result.status}")
        if result.status == "interrupted":
            return VerificationResult("inconclusive", reason="interrupted")
        return None

    def _parse(self, tool_call: dict) -> _Call:
        function = tool_call.get("function", {})
        name = function.get("name", "")
        call_id = tool_call.get("id", "") or str(uuid.uuid4())
        raw = function.get("arguments", "{}")
        try:
            arguments = json.loads(raw)
        except (TypeError, json.JSONDecodeError):
            error = ToolResult.failed(
                f"Error: Invalid JSON arguments: {redact(raw)}", "invalid_arguments"
            )
            return _Call(call_id, name, None, error)
        if not isinstance(arguments, dict):
            error = ToolResult.failed(
                "Error: Tool arguments must be an object", "invalid_arguments"
            )
            return _Call(call_id, name, None, error)
        return _Call(call_id, name, self._apply_workspace_defaults(name, arguments))

    def _apply_workspace_defaults(self, name: str, arguments: dict[str, Any]) -> dict[str, Any]:
        workspace = self._agent.workspace
        arguments = dict(arguments)
        if name == "terminal" and not arguments.get("workdir"):
            arguments["workdir"] = str(workspace)
        elif name in {"read_file", "write_file", "patch_file"}:
            path = arguments.get("path")
            if isinstance(path, str) and path and not Path(path).expanduser().is_absolute():
                arguments["path"] = str(workspace / path)
        elif name == "search_files":
            path = arguments.get("path", ".")
            if isinstance(path, str) and not Path(path).expanduser().is_absolute():
                arguments["path"] = str(workspace / path)
        elif name == "list_files":
            root = arguments.get("root", ".")
            if isinstance(root, str) and not Path(root).expanduser().is_absolute():
                arguments["root"] = str(workspace / root)
        elif name.startswith("git_"):
            repo = arguments.get("repo", ".")
            if isinstance(repo, str) and not Path(repo).expanduser().is_absolute():
                arguments["repo"] = str(workspace / repo)
        return arguments

    def _can_run_in_parallel(self, tool_call: dict) -> bool:
        name = tool_call.get("function", {}).get("name", "")
        entry = registry.get_tool(name)
        read_only = (entry is not None and entry.is_read_only) or name == MCP_RESOURCE_TOOL
        # Calls that may prompt for confirmation must run on the caller's thread.
        gated_egress = self.untrusted_content_seen and is_egress_tool(name)
        return read_only and not gated_egress

    def _guarded(self, run: Callable[[], ToolResult], tool_call: dict) -> ToolResult:
        try:
            return run()
        except Exception as exc:
            name = tool_call.get("function", {}).get("name", "")
            logger.exception("Tool call '%s' failed", name)
            error_type = type(exc).__name__
            return ToolResult.failed(f"Error: Tool '{name}' failed: {error_type}", error_type)

    def _interrupted(self) -> bool:
        check = self._agent._interrupt_check
        return check is not None and check()

    def _wait_unless_interrupted(self, seconds: float) -> bool:
        """Sleep up to ``seconds``; return True as soon as the user interrupts."""
        deadline = time.monotonic() + seconds
        while (remaining := deadline - time.monotonic()) > 0:
            if self._interrupted():
                return True
            time.sleep(min(0.1, remaining))
        return self._interrupted()

    def _confirm(self, name: str, arguments: dict[str, Any]) -> bool:
        confirm = self._agent._confirmation_callback
        return bool(confirm and confirm(name, arguments))

    def _announce(self, tool_call: dict) -> None:
        callback = getattr(self._agent, "_tool_callback", None)
        name = tool_call.get("function", {}).get("name", "")
        if callback and name:
            callback(name)

    def _report_start(self, tool_call: dict) -> None:
        callback = self._agent._tool_lifecycle_callback
        call_id = tool_call.get("id", "")
        name = tool_call.get("function", {}).get("name", "")
        if callback and call_id and name:
            callback(call_id, name, "start", None)

    def _report_result(self, tool_call: dict, result: ToolResult | None) -> None:
        callback = self._agent._tool_lifecycle_callback
        call_id = tool_call.get("id", "")
        name = tool_call.get("function", {}).get("name", "")
        if callback and call_id and name and result is not None:
            status = "completed" if result.status == "completed" else "failed"
            callback(call_id, name, status, result.content)


def _permission_path(arguments: dict[str, Any]) -> str | None:
    """Return the path-like argument that must go through policy checks."""
    for key in ("path", "file_path", "root", "repo", "workdir"):
        value = arguments.get(key)
        if isinstance(value, str) and value:
            return value
    return None
"""Retry logic with exponential backoff for API calls.

Handles transient errors (rate limits, server errors, timeouts)
with configurable retry counts, backoff multipliers, and
error classification.
"""

import logging
import random
import time
from collections.abc import Callable
from typing import Any

import httpx
import openai

logger = logging.getLogger(__name__)


# Error classifications
class ErrorType:
    RETRYABLE = "retryable"  # Transient — should retry
    NON_RETRYABLE = "non_retryable"  # Permanent — should not retry
    CONTEXT_OVERFLOW = "overflow"  # Context too long — needs deterministic compaction
    API_TIMEOUT = "api_timeout"  # API-level timeout — retry once only
    CONNECTION_TIMEOUT = "connection_timeout"  # Connection issue — retry with backoff


# HTTP status codes that are retryable
_RETRYABLE_STATUS = {429, 500, 502, 503, 504, 529}

# Error message patterns that indicate retryable errors
_RETRYABLE_PATTERNS = [
    "rate limit",
    "too many requests",
    "server error",
    "internal error",
    "bad gateway",
    "service unavailable",
    "upstream error",
]

# Connection-level errors (transient network issues — retry aggressively)
_CONNECTION_ERROR_PATTERNS = [
    "connection timeout",
    "connection refused",
    "connection reset",
]

# API-level timeouts (may be permanent — retry only once)
_API_TIMEOUT_PATTERNS = [
    "timeout",
    "timed out",
    "temporary failure",
    "gateway timeout",
]

# Error patterns that indicate context overflow
_OVERFLOW_PATTERNS = [
    "context length",
    "context window",
    "token limit",
    "maximum context",
    "prompt is too long",
    "input length",
    "exceeds the maximum",
]


def classify_error(status_code: int | None = None, message: str = "") -> str:
    """Classify an error as retryable, non-retryable, or context overflow.

    Args:
        status_code: HTTP status code (if available).
        message: Error message text.

    Returns:
        One of ErrorType.RETRYABLE, ErrorType.NON_RETRYABLE, ErrorType.CONTEXT_OVERFLOW,
        ErrorType.API_TIMEOUT, or ErrorType.CONNECTION_TIMEOUT.
    """
    text = (message or "").lower()

    # Check for context overflow first (highest priority)
    for pattern in _OVERFLOW_PATTERNS:
        if pattern in text:
            return ErrorType.CONTEXT_OVERFLOW

    # HTTP status is authoritative for API responses. Error text can contain
    # words such as "timeout" even when a request is invalid (for example 400).
    if status_code in _RETRYABLE_STATUS:
        return ErrorType.RETRYABLE

    if status_code and 400 <= status_code < 500:
        return ErrorType.NON_RETRYABLE

    if status_code and 500 <= status_code < 600:
        return ErrorType.RETRYABLE

    # Check connection-level errors first (transient network issues)
    for pattern in _CONNECTION_ERROR_PATTERNS:
        if pattern in text:
            return ErrorType.CONNECTION_TIMEOUT

    # Check API-level timeouts (may be permanent — retry only once)
    for pattern in _API_TIMEOUT_PATTERNS:
        if pattern in text:
            return ErrorType.API_TIMEOUT

    # Check general retryable error patterns
    for pattern in _RETRYABLE_PATTERNS:
        if pattern in text:
            return ErrorType.RETRYABLE

    # Unknown errors are usually programming or SDK errors. Retrying them
    # hides the original failure and cannot make a deterministic call valid.
    if status_code is None:
        return ErrorType.NON_RETRYABLE

    # Default: non-retryable for known non-retryable status codes
    return ErrorType.NON_RETRYABLE


def classify_exception(error: Exception) -> str:
    """Classify a raised exception, trusting its type before its message.

    SDK transport errors carry generic messages (openai's is just
    "Connection error.") that text patterns cannot recognize.
    """
    if isinstance(error, (openai.APITimeoutError, httpx.TimeoutException, TimeoutError)):
        return ErrorType.API_TIMEOUT
    if isinstance(error, (openai.APIConnectionError, httpx.TransportError, ConnectionError)):
        return ErrorType.CONNECTION_TIMEOUT
    # httpx.HTTPStatusError stores status_code on .response
    status_code = getattr(error, "status_code", None)
    if status_code is None:
        response = getattr(error, "response", None)
        if response is not None:
            status_code = getattr(response, "status_code", None)
    return classify_error(status_code, str(error))


def retry_with_backoff(
    func,
    *args: Any,
    max_retries: int = 3,
    base_delay: float = 1.0,
    max_delay: float = 60.0,
    backoff_multiplier: float = 2.0,
    jitter: bool = True,
    retry_if: Callable[[Exception], bool] | None = None,
    **kwargs: Any,
) -> Any:
    """Call a function with exponential backoff retry.

    Args:
        func: Function to call. Should raise an exception on failure.
        *args: Positional arguments for the function.
        max_retries: Maximum number of retry attempts.
        base_delay: Initial delay in seconds.
