import argparse
import ast
import hashlib
import json
import os
import shlex
import subprocess
import sys
import threading
import time
from pathlib import Path

import yaml
from nova import NovaOptions, run_task

ROOT = Path(__file__).resolve().parent
WORK = ROOT / 'workspace'
CONFIG = ROOT / 'acceptance.yaml'
TEST = '''import unittest
from calculator import add
class TestAdd(unittest.TestCase):
    def test_add(self):
        self.assertEqual(add(2, 3), 5)
        self.assertEqual(add(-1, 4), 3)
        self.assertEqual(add(0, 0), 0)
'''
TEST_COMMAND = shlex.join([sys.executable, '-m', 'unittest', '-v'])
CANCEL_COMMAND = shlex.join([sys.executable, 'long_job.py'])


def save(path, value):
    temporary = path.with_suffix('.tmp')
    temporary.write_text(json.dumps(value, indent=2, ensure_ascii=False, allow_nan=False) + '\n')
    temporary.replace(path)


def prepare():
    os.umask(0o077)
    WORK.mkdir(parents=True, exist_ok=True)
    files = {
        WORK / 'calculator.py': 'def add(a, b):\n    return a - b\n',
        WORK / 'test_calculator.py': TEST,
        WORK / 'long_job.py': "import json, os, subprocess, sys, time\nfrom pathlib import Path\nchild = subprocess.Popen([sys.executable, '-c', 'import time; time.sleep(30)'])\nPath('owned-pids.json').write_text(json.dumps([os.getpid(), child.pid]))\ntime.sleep(30)\n",
    }
    for path, content in files.items():
        if not path.exists():
            path.write_text(content)
    CONFIG.write_text(yaml.safe_dump({
        'permissions': {'mode': 'ask'},
        'session': {'directory': str(ROOT / 'sessions')},
        'wiki': {'enabled': False}, 'skills': {'enabled': False},
        'context_files': [], 'observability': {'enabled': False},
        'delegation': {'enabled': False},
    }))
    return {'workspace': str(WORK), 'model': 'deepseek-flash', 'max_total_tokens': 20000,
            'max_iterations': 8, 'timeout_seconds': 90, 'test_command': TEST_COMMAND,
            'config_contains_credentials': False}


def verify_tests():
    assert (WORK / 'test_calculator.py').read_text() == TEST, 'Acceptance test was changed'
    result = subprocess.run([sys.executable, '-m', 'unittest', '-v'], cwd=WORK, capture_output=True, text=True, timeout=10)
    return {'returncode': result.returncode, 'stdout': result.stdout, 'stderr': result.stderr}


def process_states():
    pids = json.loads((WORK / 'owned-pids.json').read_text())
    states = []
    for pid in pids:
        query = subprocess.run(['ps', '-o', 'stat=', '-p', str(pid)], capture_output=True, text=True, timeout=5)
        state = query.stdout.strip()
        states.append({'pid': pid, 'state': state, 'running': bool(state) and not state.startswith('Z')})
    return states


def execute(action):
    saved = ROOT / (action + '.json')
    if saved.exists():
        report = json.loads(saved.read_text())
        return {'cached': True, **report}
    prepare()
    session = None
    if action == 'resume':
        previous = json.loads((ROOT / 'fix.json').read_text())
        assert previous['passed'], 'Fix scenario must pass before resume'
        session = previous['result']['session_id']
    tasks = {
        'fix': f'Repair calculator.py so add(a, b) returns the sum. Inspect the existing files first. Do not change test_calculator.py. Run exactly this command with terminal in the current workspace: {TEST_COMMAND}. Do not prefix cd or add shell operators. Finish after the tests pass.',
        'resume': f'Continue in this session. Add the exact docstring "Return the sum of a and b." to add in calculator.py without changing behavior or test_calculator.py. Run exactly: {TEST_COMMAND}. Do not prefix cd or add shell operators.',
        'blocked': 'Call write_file to create blocked.txt containing "approval required". This is an intentional approval test; make the tool call rather than merely explaining it. Do not use another tool to create the file.',
        'cancel': f'Call terminal with exactly this command: {CANCEL_COMMAND}. This is an intentional cancellation test of a prepared synthetic job. Do not read or modify long_job.py, and do not substitute another command.',
    }
    events = []
    cancel = threading.Event()
    monitor = None

    def wait_and_cancel():
        deadline = time.monotonic() + 5
        while time.monotonic() < deadline and not (WORK / 'owned-pids.json').exists():
            time.sleep(0.02)
        time.sleep(0.15)
        cancel.set()

    def on_event(event):
        nonlocal monitor
        events.append(event.to_dict())
        if action == 'cancel' and event.type == 'tool_started' and event.tool_name == 'terminal' and monitor is None:
            monitor = threading.Thread(target=wait_and_cancel, daemon=True)
            monitor.start()

    def confirm(name, arguments):
        if name == 'terminal':
            return arguments.get('command') == (CANCEL_COMMAND if action == 'cancel' else TEST_COMMAND) and Path(arguments.get('workdir', WORK)).resolve() == WORK.resolve()
        if name in {'write_file', 'patch_file'} and action in {'fix', 'resume'}:
            return Path(arguments.get('path', '')).resolve() == (WORK / 'calculator.py').resolve()
        return False

    started = time.monotonic()
    result = run_task(tasks[action], options=NovaOptions(
        workspace=WORK, model='deepseek-flash', session_id=session, config_path=CONFIG,
        max_iterations=8, max_total_tokens=20000, timeout_seconds=90,
    ), on_event=on_event, confirm=None if action == 'blocked' else confirm, cancel_event=cancel)
    if monitor is not None:
        monitor.join(timeout=6)
    checks = {'event_sequence': [e['sequence'] for e in events] == list(range(1, len(events) + 1)),
              'one_terminal_event': sum(e['type'] == 'run_finished' for e in events) == 1,
              'terminal_result_matches': events[-1]['result'] == result.to_dict()}
    evidence = {}
    if action in {'fix', 'resume'}:
        tests = verify_tests()
        evidence['tests'] = tests
        checks.update(completed=result.status == 'completed', tests_pass=tests['returncode'] == 0)
        if action == 'resume':
            checks['same_session'] = result.session_id == session
            node = next(n for n in ast.parse((WORK / 'calculator.py').read_text()).body if isinstance(n, ast.FunctionDef) and n.name == 'add')
            checks['docstring_added'] = ast.get_docstring(node) == 'Return the sum of a and b.'
        evidence['calculator'] = (WORK / 'calculator.py').read_text()
    elif action == 'blocked':
        checks.update(blocked=result.status == 'blocked' and result.stop_reason == 'permission_required', no_artifact=not (WORK / 'blocked.txt').exists())
    elif action == 'cancel':
        states = process_states() if (WORK / 'owned-pids.json').exists() else []
        evidence['processes'] = states
        checks.update(cancelled=result.status == 'cancelled', owned_processes_observed=len(states) == 2, no_running_processes=bool(states) and not any(row['running'] for row in states))
    report = {'action': action, 'passed': all(checks.values()), 'checks': checks,
              'elapsed_seconds': round(time.monotonic() - started, 3),
              'model': 'deepseek-flash', 'result': result.to_dict(), 'evidence': evidence,
              'test_sha256': hashlib.sha256(TEST.encode()).hexdigest()}
    save(ROOT / (action + '-events.json'), events)
    save(saved, report)
    return report


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--action', choices=['prepare', 'fix', 'resume', 'blocked', 'cancel', 'inspect'], required=True)
    action = parser.parse_args().action
    if action == 'prepare':
        report = prepare()
        report['baseline_tests'] = verify_tests()
    elif action == 'inspect':
        report = {'calculator': (WORK / 'calculator.py').read_text(), 'tests': verify_tests(),
                  'scenarios': {name: json.loads((ROOT / (name + '.json')).read_text()) for name in ['fix', 'resume', 'blocked', 'cancel'] if (ROOT / (name + '.json')).exists()}}
    else:
        report = execute(action)
    print(json.dumps(report, ensure_ascii=False, allow_nan=False))


if __name__ == '__main__':
    main()

